 const review=(id,extra={})=>({id,status:'review',revision:1,body:{sourceFile:'synthetic.xlsx',variants:[{record:record({anesthetics:'injection'}),sources:[{sheet:'2020',row:2}]},{record:record(extra),sources:[{sheet:'통합',row:2}]}]}});
 const adapter={identity:()=> 'synthetic-case-test',ready:()=>true,can:()=>!reader,clinicName:()=> '합성 검증 병원',request:async(path,options={})=>{await new Promise(r=>setTimeout(r,1));requests.push(path);if(failGet&&!options.method&&/\/ledger\/[^/?]+$/.test(path)&&!path.endsWith('/preferences'))throw Error('합성 조회 실패');const data=options.body?JSON.parse(options.body):null;if(options.method==='POST'){posts.push({path,body:copy(data)});if(failAt===posts.length)throw Error('합성 저장 실패');}
  if(pendingSource&&path.startsWith(pendingSource.prefix)){const pending=pendingSource;pendingSource=null;await new Promise(resolve=>pending.release=resolve);}
  if(path==='/members'){if(failMembers)throw Error('합성 직원 조회 실패');return {members:copy(memberItems)};}
  if(path.endsWith('/preferences')){if(failPrefs&&!data)throw Error('합성 설정 조회 실패');if(data){if(data.revision!==settings.revision)throw Error('설정 버전 충돌');settings={...data,revision:settings.revision+1};}return copy(settings);}
  if(failPatients&&path.startsWith('/patient-directory?'))throw Error('합성 환자 조회 실패');
  if(path.startsWith('/patient-directory?'))return {patients:[{id:'p2',name:'새 합성환자',chartNumber:'SYN002',species:'cat'}]};
  if(path.startsWith('/practice/support/bookings?'))return {items:bookingItems||[{status:'booked',body:{patientName:'합성환자',title:'일정 수술',patientId:'',chartNumber:''}}]};
  if(path.startsWith('/practice/clinical/cases?'))return {items:[{kind:'surgery',body:{anesthesiaSheet:{operation:'마취기록 수술',diagnosis:'마취기록 진단'}}}]};
  if(path.endsWith('/import')){let inserted=0;for(const item of data.items){if(docs.some(d=>d.body.sourceKey===item.sourceKey&&d.body.sourceFile===data.file))continue;docs.push({id:'import-'+docs.length,status:item.variants.length>1?'review':'active',revision:1,body:{sourceKey:item.sourceKey,sourceFile:data.file,variants:copy(item.variants),...(item.variants.length===1?{record:copy(item.variants[0].record)}:{})}});inserted++;}return {inserted};}
  if(path.includes('?')){if(failList)throw Error('합성 목록 조회 실패');const q=new URLSearchParams(path.split('?')[1]),offset=Number(q.get('before')||0),filtered=docs.filter(d=>{const r=d.body.record||d.body.variants?.[0]?.record||{};return d.status===q.get('status')&&(!q.get('q')||JSON.stringify(d.body).includes(q.get('q')))&&(!q.get('from')||r.date>=q.get('from'))&&(!q.get('to')||r.date<=q.get('to'));}),items=filtered.slice(offset,offset+2),counts=Object.fromEntries(['active','review','deleted'].map(s=>[s,docs.filter(d=>d.status===s).length]));return copy({items,next:offset+2<filtered.length?String(offset+2):'',counts});}
  const tail=path.split('/ledger')[1].split('/').filter(Boolean),id=tail[0],action=tail[1],old=docs.find(d=>d.id===id);
  if(!data)return {document:copy(old)};
  if(old&&data.revision!==old.revision)throw Error('버전 충돌');
  if(action==='resolve'){if(old.status!=='review'||!old.body.variants[data.selected])throw Error('선택 필요');old.body.record=copy(old.body.variants[data.selected].record);old.body.selected=data.selected;old.body.resolvedAt=new Date().toISOString();old.status='active';old.revision++;return {document:copy(old)};}
  if(action==='delete'||action==='restore'){old.status=action==='delete'?'deleted':'active';old.revision++;return {document:copy(old)};}
  if(old&&old.status!=='active')throw Error('원본 비교 또는 복원을 먼저 완료해주세요.');
  const d={...(old||{}),id:id||'new-'+docs.length,status:'active',revision:(old?.revision||0)+1,body:{...old?.body,record:copy(data.record)}};if(old)docs[docs.indexOf(old)]=d;else docs.push(d);return {document:copy(d)};
 }};
 async function reset(options={}){view?.dispose();docs=options.docs||[review('case'),review('real',{anesthetics:'Injection 2 mL'})];posts=[];requests=[];downloads=[];failGet=false;failPrefs=false;failList=false;failPatients=false;pendingSource=null;memberItems=options.members||[{userId:'s1',displayName:'합성 원장',status:'active'},{userId:'s2',displayName:'합성 직원',status:'active'},{userId:'s3',displayName:'비활성 직원',status:'inactive'}];failMembers=false;bookingItems=options.bookings||null;failAt=0;reader=!!options.reader;settings={revision:0,surgeons:[],assistants:[],anesthetists:[],procedures:[],anesthetics:[],drugs:[],...options.settings};view=SurgeryLedger.mount(document.querySelector('#root'),adapter);await view.open();}
 window.LedgerCaseFixture={reset,review,record,failMembers:v=>failMembers=v,failPatients:v=>failPatients=v,holdSource:prefix=>{const pending={prefix};pendingSource=pending;return pending;},fail:v=>failAt=v,failRead:v=>failGet=v,failPreferences:v=>failPrefs=v,failListing:v=>failList=v,get requests(){return requests;},get downloads(){return downloads;},get docs(){return docs;},get posts(){return posts;},get settings(){return settings;}};void reset();
