 await test('설정 저장 자체가 실패하면 입력 유지·다시 저장 가능',async()=>{await click('[data-ledger=settings]');fill('surgeons','미저장 집도의');F.fail(1);await click('[data-ledger=save-settings]');check(F.settings.revision===0&&!$('[data-ledger=save-settings]').disabled&&$('[name=surgeons]').value==='미저장 집도의','설정 저장 실패 복구 불가');F.fail(0);await click('[data-ledger=save-settings]');check(F.settings.revision===1,'설정 저장 재시도 실패');});

 await test('설정 지연 응답이 저장 중 새 입력 컨트롤을 활성화하지 않음',async()=>{await F.reset({docs:[{id:'saved',status:'active',revision:1,body:{record:F.record()}}],settings:{procedures:['선택 수술']}});const prefs=F.holdSource('/practice/support/ledger/preferences');await click('[data-ledger=open]');for(let i=0;i<100&&!prefs.release;i++)await new Promise(r=>setTimeout(r,10));fill('procedure','저장할 수술');const saving=F.holdSource('/practice/support/ledger/saved');$('[data-ledger=save]').click();for(let i=0;i<100&&!saving.release;i++)await new Promise(r=>setTimeout(r,10));prefs.release();await preferencesSettled();const disabled=$('[data-preset=procedure]')?.disabled;saving.release();await ready();check(disabled&&F.docs[0].body.record.procedure==='저장할 수술','저장 중 새 선택 항목 활성화 또는 내용 손실');});

 function choose(key,value){const select=$('[data-choice="'+key+'"]');check(select,'선택 메뉴 없음 '+key);select.value=value;select.dispatchEvent(new(w().Event)('change',{bubbles:true}));}
 for(const width of [1200,390]){frame.style.width=width+'px';
  await test('마취 방법·약물 기본 드롭다운 및 빈 초기값 '+width,async()=>{await click('[data-ledger=new]');for(const [key,values] of [['anesthetics',['Injection','Inhalation','직접입력']],['drug',['Propofol','Ketamine','medetomidine','직접입력']]]){check(values.every(v=>[...$('[data-choice='+key+']').options].some(o=>o.textContent===v)),'기본 선택 항목 누락');check($('[name='+key+']').value===''&&$('[name='+key+']').hidden,'초기 자동 선택 또는 큰 입력칸 노출');}check($('[data-choice-field=anesthetics]').textContent.includes('마취 방법')&&$('[data-choice-field=drug]').textContent.includes('마취 약물'),'명칭 미반영');check(d().documentElement.scrollWidth<=width+1,'드롭다운 가로 넘침');});
  await test('방법 선택·복수 약물·중복 방지·개별 삭제·저장 복원 '+width,async()=>{await click('[data-ledger=new]');fill('patientName','선택 검증');fill('procedure','합성 수술');choose('anesthetics','Inhalation');choose('drug','Ketamine');choose('drug','medetomidine');choose('drug','Ketamine');check($('[name=drug]').value==='Ketamine, medetomidine','복수 선택 또는 중복 제거 실패');await click('[data-choice-remove="0"]');check($('[name=drug]').value==='medetomidine','개별 삭제 실패');choose('drug','Propofol');await click('[data-ledger=save]');check(F.docs.at(-1).body.record.anesthetics==='Inhalation'&&F.docs.at(-1).body.record.drug==='medetomidine, Propofol','선택 값 저장 실패');check($('[data-choice=anesthetics]').value==='Inhalation'&&d().querySelectorAll('[data-choice-remove]').length===2,'저장 후 선택 복원 실패');await click('[data-ledger=back]');await click('[data-ledger=open]');await preferencesSettled();check($('[name=drug]').value==='medetomidine, Propofol'&&$('[name=drug]').hidden,'재조회 시 선택 손실');});
  await test('직접입력 전환·사용자 입력·저장 실패 유지 '+width,async()=>{await click('[data-ledger=new]');fill('patientName','직접입력 검증');fill('procedure','합성 수술');choose('anesthetics','Injection');choose('anesthetics','__custom__');check(!$('[name=anesthetics]').hidden&&$('[name=anesthetics]').value==='Injection','직접입력 전환 시 값 손실');fill('anesthetics','Inhalation + local');choose('drug','__custom__');fill('drug','사용자 약물\n별도 기록');choose('drug','Propofol');check($('[name=drug]').value==='사용자 약물\n별도 기록, Propofol','직접입력과 선택 병용 실패');F.fail(1);await click('[data-ledger=save]');check($('[name=anesthetics]').value==='Inhalation + local'&&$('[name=drug]').value==='사용자 약물\n별도 기록, Propofol','저장 실패 시 입력 손실');F.fail(0);await click('[data-ledger=save]');check(!$('[name=drug]').hidden&&F.docs.at(-1).body.record.drug==='사용자 약물\n별도 기록, Propofol','직접입력 저장 복원 실패');});
  await test('기존 복수 약물·비표준 표기 수정 없이 저장 시 보존 '+width,async()=>{for(const drug of ['Ketamine, medetomidine','기존 약물 2 mL\n상세 메모, 기타']){await F.reset({docs:[{id:'legacy',status:'active',revision:1,body:{record:F.record({anesthetics:'기존 방법 기록',drug})}}]});await click('[data-ledger=open]');await preferencesSettled();check($('[data-choice=anesthetics]').value==='__custom__'&&!$('[name=anesthetics]').hidden,'기존 방법 미표시');await click('[data-ledger=save]');check(F.docs[0].body.record.drug===drug,'기존 약물 문자열 손실');}check(d().documentElement.scrollWidth<=width+1,'기존 기록 넘침');});
 }
