 await test('구형 엑셀 마취제·사용 약물 제목을 새 명칭으로 호환',async()=>{const fields=w().SurgeryLedger.fields,method=fields.find(x=>x[0]==='anesthetics'),drug=fields.find(x=>x[0]==='drug'),old=[method[1],drug[1]],record=F.record({anesthetics:'Inhalation',drug:'Ketamine, medetomidine'});let bytes;try{method[1]='마취제';drug[1]='사용 약물';bytes=w().SurgeryLedger.workbookBytes([record]);}finally{[method[1],drug[1]]=old;}const parsed=await w().SurgeryLedger.workbookRows(new(w().File)([bytes],'legacy.xlsx'));check(parsed.rows[0].record.anesthetics==='Inhalation'&&parsed.rows[0].record.drug===record.drug,'구형 제목 약물 값 누락');const latest=w().SurgeryLedger.workbookBytes([record]),content=new TextDecoder().decode(latest);check(content.includes('마취 방법')&&content.includes('마취 약물'),'새 엑셀 제목 누락');check(w().SurgeryLedger.printHTML([record]).includes('마취 방법·약물'),'인쇄 제목 미반영');});
 await test('설정에서 추가한 항목도 기본 선택지와 함께 유지',async()=>{await F.reset({docs:[{id:'configured',status:'active',revision:1,body:{record:F.record()}}],settings:{anesthetics:['병원 방법'],drugs:['병원 약물']}});await click('[data-ledger=open]');await preferencesSettled();check([...$('[data-choice=anesthetics]').options].some(x=>x.value==='병원 방법')&&[...$('[data-choice=drug]').options].some(x=>x.value==='병원 약물'),'병원별 추가 항목 누락');choose('anesthetics','병원 방법');choose('drug','병원 약물');await click('[data-ledger=save]');check(F.docs[0].body.record.anesthetics==='병원 방법'&&F.docs[0].body.record.drug==='병원 약물','추가 항목 저장 실패');});

