  await test('직접입력 동물종·미등록 품종과 과거 직원 이름 보존 '+width,async()=>{await F.reset({docs:[{id:'past',status:'active',revision:1,body:{record:F.record({species:'개',breed:'기존 한글 품종',surgeon:'퇴사한 집도의'})}}]});await click('[data-ledger=open]');await staffSettled();await preferencesSettled();check($('[data-choice=species]').value==='Canine'&&$('[name=breed]').value==='기존 한글 품종','기존 기록 열 때 변경');check($('[data-choice=surgeon]').value==='__custom__'&&$('[name=surgeon]').value==='퇴사한 집도의','과거 집도의 손실');await click('[data-ledger=save]');check(F.docs[0].body.record.breed==='기존 한글 품종'&&F.docs[0].body.record.species==='개','수정 없는 기존 데이터 변경');choose('species','__custom__');fill('species','Rabbit');fill('breed','Custom Rabbit Breed');await click('[data-ledger=save]');check(F.docs[0].body.record.species==='Rabbit'&&F.docs[0].body.record.breed==='Custom Rabbit Breed','기타 종 직접입력 손실');});
